def transform(grid):
    h, w = len(grid), len(grid[0])
    divider_row = next((r for r, row in enumerate(grid)
                        if len(set(row)) == 1 and h > 1), None)
    divider_col = next((c for c in range(w)
                        if len({grid[r][c] for r in range(h)}) == 1 and w > 1), None)

    def background(cells):
        return Counter(cells).most_common(1)[0][0]

    if divider_row is not None:
        top, bottom = grid[:divider_row], grid[divider_row + 1:]
        if all(v in (0, 8) for row in top for v in row) and all(v in (0, 3) for row in bottom for v in row):
            return [[2 if top[r][c] == 8 and bottom[r][c] == 3 else 0
                     for c in range(w)] for r in range(min(len(top), len(bottom)))]
        # White/zero background: retain only foreground cells in both panels.
        return [[2 if top[r][c] != 0 and bottom[r][c] != 0 else 0
                 for c in range(w)] for r in range(min(len(top), len(bottom)))]
    if divider_col is not None:
        left = [row[:divider_col] for row in grid]
        right = [row[divider_col + 1:] for row in grid]
        # Panels with nonzero backgrounds use each half's dominant color;
        # panels with zero background use the shared foreground intersection.
        bg_left = background([v for row in left for v in row])
        bg_right = background([v for row in right for v in row])
        if bg_left == 0 and bg_right == 0:
            predicate = lambda a, b: a != 0 and b != 0
        elif bg_left == 0:
            predicate = lambda a, b: a == 0 and b != bg_right
        elif bg_right == 0:
            predicate = lambda a, b: a != bg_left and b == 0
        else:
            predicate = lambda a, b: a != bg_left and b != bg_right
        return [[2 if predicate(left[r][c], right[r][c]) else 0
                 for c in range(min(len(left[r]), len(right[r])))]
                for r in range(h)]
    raise ValueError('No full uniform divider found')", "exit_code": 0, "error": null}

